+++ best
@@ -35,6 +35,31 @@
     const char* end = buf + len;
     size_t count = 0;
     while (p < end) {
+        // Fast path: optional '-', then 1..19 digits, then '\n'
+        const char* q = p;
+        bool neg = false;
+        if (*q == '-') { neg = true; ++q; }
+        if (*q < '0' || *q > '9') goto fallback;
+        uint64_t mant = 0;
+        int digits = 0;
+        while (*q >= '0' && *q <= '9') {
+            if (digits < 19) {
+                mant = mant * 10 + (*q - '0');
+                ++digits;
+            } else {
+                // Too many digits: fallback to strtod for correct rounding
+                goto fallback;
+            }
+            ++q;
+        }
+        if (*q != '\n') goto fallback;
+        // Convert mantissa to double (exact for <= 2^53)
+        double d = (double)mant;
+        if (neg) d = -d;
+        out[count++] = d;
+        p = q + 1;
+        continue;
+    fallback:
         char* next;
         out[count++] = std::strtod(p, &next);
         p = next;
